from gpiozero import PWMOutputDevice
import time
import signal
import sys

# GPIO pins for the PWM channels (BCM numbering)
PWM_CHANNEL_PINS = [12, 20, 21]

# Global PWM objects
pwm_channels = []


def setup_pwm_channels():
    """Create and start PWM output devices for each channel."""
    global pwm_channels
    pwm_channels = [
        PWMOutputDevice(pin, frequency=1000.0)
        for pin in PWM_CHANNEL_PINS
    ]


def set_channel_duty_cycle(channel_index, duty_cycle_value):
    """Set the duty cycle for a specific PWM channel."""
    if 0 <= channel_index < len(pwm_channels):
        pwm_channels[channel_index].value = duty_cycle_value
    else:
        print("Invalid channel index")


def report_channel_state(channel_index):
    """Print the current duty cycle state of a channel."""
    if 0 <= channel_index < len(pwm_channels):
        print(f"Channel {channel_index} duty cycle: {pwm_channels[channel_index].value}")
    else:
        print("Invalid channel index")


def cleanup_channels():
    """Stop all PWM channels and release the GPIO resources."""
    for pwm_channel in pwm_channels:
        pwm_channel.close()


def signal_handler(signal_number, frame):
    """Handle interrupt signals for clean exit."""
    print("\nExiting program...")
    cleanup_channels()
    sys.exit(0)


if __name__ == "__main__":
    # Set up interrupt handling for graceful exit
    signal.signal(signal.SIGINT, signal_handler)

    # Initialize the PWM channels
    setup_pwm_channels()

    try:
        while True:
            # Cycle through the channels and report state
            for channel_index in range(len(pwm_channels)):
                set_channel_duty_cycle(channel_index, 0.5)
                report_channel_state(channel_index)
                time.sleep(0.03)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Ensure channels are cleaned up on exit
        cleanup_channels()

