from gpiozero import PWMOutputDevice
import time

# BCM pins for the PWM channels on the Raspberry Pi
PWM_CHANNEL_PINS = [4, 17, 22, 27]

def create_pwm_channels():
    """Create and return a list of PWMOutputDevice channels."""
    # Configure each pin as a PWM-capable output
    pwm_channels = [PWMOutputDevice(pin) for pin in PWM_CHANNEL_PINS]
    return pwm_channels

def apply_states(pwm_channels, states):
    """Apply a list of duty cycle states to the PWM channels."""
    # Set each channel to the corresponding duty cycle value
    for channel, duty in zip(pwm_channels, states):
        channel.value = duty

def read_duty_cycle():
    """Read a duty cycle value from standard input, or return None on error."""
    # Allow the user to override a duty cycle value
    duty_value = input("Enter duty cycle (0.0-1.0), or leave blank: ")
    if not duty_value:
        return None
    try:
        return float(duty_value)
    except ValueError:
        return None

def main():
    # Configure the PWM channels for the LED strip
    pwm_channels = create_pwm_channels()
    try:
        while True:
            # Read the desired duty cycle from the user
            duty_value = read_duty_cycle()
            # Apply the duty cycle to every channel
            apply_states(pwm_channels, [duty_value] * len(pwm_channels))
            # Wait for one second before the next update
            time.sleep(1)
    except KeyboardInterrupt:
        # Stop updating when the user interrupts the program
        print("Stopping LED strip control")
    finally:
        # Release all PWM channels when the program exits
        for channel in pwm_channels:
            channel.close()

if __name__ == "__main__":
    main()

# serial data exchange with a device on a Raspberry Pi
# Reads one reading per second and prints it to standard output
import serial
import time

# UART port and baud rate for the connected device
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600


def read_device_reading(serial_connection):
    """Read a single line of data from the serial device."""
    # Attempt to read a line and return it, or an empty string on error
    try:
        return serial_connection.readline().decode("utf-8", "ignore").strip()
    except serial.SerialException:
        return ""


def validate_reading(reading_text):
    """Return True when the reading passes a basic validity check."""
    # A non-empty reading indicates a successful communication
    return bool(reading_text)


def main():
    # Open the serial port for the Raspberry Pi
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    try:
        # Continuously read and print device readings
        while True:
            reading_text = read_device_reading(serial_connection)
            if validate_reading(reading_text):
                print("Device reading:", reading_text)
            time.sleep(1)
    except KeyboardInterrupt:
        # Stop reading on user interrupt
        print("Reading stopped")
    finally:
        # Always close the serial port
        serial_connection.close()
        print("Serial port closed")


if __name__ == "__main__":
    main()

from gpiozero import PWMOutputDevice
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins using BCM numbering
LED_PINS = {
    "red": 12,
    "green": 13,
    "blue": 18,
    "yellow": 19,
    "white": 22,
    "magenta": 23,
}

class LEDController:
    """
    Controls a set of LEDs connected to PWM-capable GPIO pins.

    Provides methods for setting the brightness of each LED and a cleanup method.
    """

    def __init__(self, pin_mapping):
        """
        Initializes the LEDController with a mapping of LED names to GPIO pins.

        Args:
            pin_mapping (dict): A dictionary mapping LED names (strings) to GPIO pin numbers (integers).
        """
        self.leds = {}
        for led_name, pin_number in pin_mapping.items():
            try:
                self.leds[led_name] = PWMOutputDevice(pin=pin_number, frequency=1000)
                logging.info(f"Initialized {led_name} LED on pin {pin_number}")
            except Exception as e:
                logging.error(f"Failed to initialize {led_name} LED on pin {pin_number}: {e}")
                raise  # Re-raise the exception to halt execution

    def set_brightness(self, led_name, brightness):
        """
        Sets the brightness of the specified LED.

        Args:
            led_name (str): The name of the LED to control.
            brightness (float): The desired brightness level (0.0 to 1.0).
        """
        if led_name in self.leds:
            try:
                self.leds[led_name].value = brightness
                logging.debug(f"Set {led_name} brightness to {brightness}")
            except Exception as e:
                logging.error(f"Failed to set {led_name} brightness to {brightness}: {e}")
        else:
            logging.warning(f"LED named '{led_name}' not found.")

    def cleanup(self):
        """
        Releases all PWM resources.  Call this before exiting to prevent resource leaks.
        """
        for led in self.leds.values():
            try:
                led.close()
                logging.info("Released PWM resources.")
            except Exception as e:
                logging.error(f"Failed to release PWM resources: {e}")


def main():
    """
    Main function to control the LEDs based on user input.
    """
    try:
        led_controller = LEDController(LED_PINS)

        while True:
            led_name = input("Enter LED color (red, green, blue, yellow, white, magenta), or 'exit': ").lower()
            if led_name == "exit":
                break

            try:
                brightness = float(input("Enter brightness (0.0-1.0): "))
                if 0 <= brightness <= 1:
                    led_controller.set_brightness(led_name, brightness)
                    print(f"{led_name} set to {brightness}")
                else:
                    print("Invalid brightness value. Please enter a number between 0 and 1.")
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 1.")

            time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if 'led_controller' in locals():  # Check if led_controller was initialized
            led_controller.cleanup()


if __name__ == "__main__":
    main()

import time
import logging
from functools import partial
from typing import Tuple

from adafruit_mcp3xxx import MCP3008
from adafruit_mcp3xxx.mcp3008 import MCP3008 as MCP3008Channel

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SAMPLE_INTERVAL_SECONDS = 60
ADC_CHANNELS: Tuple[MCP3008Channel, ...] = (MCP3008Channel.CHANNEL_0, MCP3008Channel.CHANNEL_1, MCP3008Channel.CHANNEL_2, MCP3008Channel.CHANNEL_3)

def read_adc_channel(mcp: MCP3008, channel: MCP3008Channel) -> int:
    """Reads a single ADC channel and returns the value."""
    try:
        return mcp.read(channel)
    except Exception as e:
        logging.error(f"Error reading ADC channel: {e}")
        return None

def read_all_adc_channels(mcp: MCP3008) -> Tuple[int, ...]:
    """Reads all configured ADC channels and returns a tuple of values."""
    return tuple(read_adc_channel(mcp, channel) for channel in ADC_CHANNELS)

def log_adc_values(values: Tuple[int, ...]) -> None:
    """Logs the ADC values in a formatted string."""
    formatted_values = ", ".join(f"{i}: {v}" for i, v in enumerate(values) if v is not None)
    if formatted_values:
        logging.info(f"ADC Values: [{formatted_values}]")
    else:
        logging.warning("No valid ADC values read.")

def main_loop(mcp: MCP3008) -> None:
    """Main loop to continuously read and log ADC values."""
    read_all = partial(read_all_adc_channels, mcp)
    try:
        while True:
            values = read_all()
            log_adc_values(values)
            time.sleep(SAMPLE_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        logging.info("Exiting program.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for MCP3008 object, but including for potential future expansion
        logging.info("Program finished.")

def initialize_mcp3008() -> Tuple[MCP3008, None]:
    """Initializes the MCP3008 ADC."""
    try:
        mcp = MCP3008()
        return mcp, None
    except Exception as e:
        logging.error(f"Failed to initialize MCP3008: {e}")
        return None, type(e)

def main() -> None:
    """Entry point for the ADC monitoring program."""
    mcp, error = initialize_mcp3008()
    if mcp is None:
        exit(1 if error else 0)

    main_loop(mcp)

if __name__ == "__main__":
    main()
